ui.css:
.hud-panel { background: #fff4de; border: 4px solid #3a2240; border-radius: 20px; box-shadow: 0 5px 0 #3a2240; padding: 2px 24px 7px; color: #3a2240; font-family: 'Fredoka', 'Baloo 2', system-ui, sans-serif; }
.hud-number { font-family: 'Lilita One', 'Fredoka', sans-serif; font-size: 36px; letter-spacing: 1.5px; color: #ff8a2a; text-shadow: 2.5px 0 0 #3a2240, -2.5px 0 0 #3a2240, 0 2.5px 0 #3a2240, 0 -2.5px 0 #3a2240, 1.8px 1.8px 0 #3a2240, -1.8px 1.8px 0 #3a2240, 1.8px -1.8px 0 #3a2240, -1.8px -1.8px 0 #3a2240, 0 5px 0 #3a2240; }
.hud-label { font: 600 12px 'Fredoka', sans-serif; letter-spacing: 1.6px; color: #8a6280; }
.bar { position: relative; height: 32px; background: #563a5e; border: 4px solid #3a2240; border-radius: 17px; box-shadow: 0 4px 0 #3a2240, inset 0 4px 0 rgba(0,0,0,.25); overflow: hidden; }
.bar-fill { position: relative; height: 100%; background: linear-gradient(180deg, #ff9a9a 0%, #ff5466 48%, #df3550 100%); border-radius: 0 13px 13px 0; box-shadow: inset 0 -3px 0 rgba(0,0,0,.12); }
.bar-fill::after { content: ''; position: absolute; left: 9px; right: 12px; top: 4px; height: 5px; border-radius: 3px; background: rgba(255,255,255,.55); }
.bar.alt .bar-fill { background: linear-gradient(180deg, #9af7d8 0%, #45d6ad 50%, #2cb892 100%); }
.card { background: linear-gradient(180deg, #ffd27f 0, #ffb24c 92px, #fff6e4 92px); border: 5px solid #3a2240; border-radius: 28px; box-shadow: 0 9px 0 #3a2240, 0 18px 30px rgba(20,8,30,.35); transition: transform .14s cubic-bezier(.3,1.6,.5,1); }
.card:hover { transform: translateY(-10px) rotate(-1.5deg) scale(1.03); }
